#include "robotblocks_runtime.h"


static void proceso_1() {
    static RbProcessState s;
    PT_BEGIN(s);
    while (true) {
        digitalWrite(13, 1);
        PT_SLEEP(s, 500);
        digitalWrite(13, 0);
        PT_SLEEP(s, 500);
        PT_YIELD(s);
    }
    PT_END(s);
}

void setup() { Serial.begin(115200); pinMode(13, OUTPUT); }

void loop() { rb_error_repeat(); proceso_1(); }
